1	// Acceptance test for the change request:
2	//   "On a client's page show me how many projects and contacts they have."
3	//
4	// A client's detail page (client-detail-page, at /clients/<id>) surfaces a counts region
5	// (client-counts) stating how many projects (client-projects-count) and how many contacts
6	// (client-contacts-count) THAT client has. The counts are scoped to the client being viewed —
7	// another client's projects and contacts are not counted — and they track the data: a client with
8	// none shows zero, and adding a contact bumps the contacts count.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed (the app's /__test__
11	// endpoint): `clients` honours { id, name, email }, `projects` honours { id, name, clientId } and
12	// `contacts` honours { id, name, email, role, clientId }.
13	//
14	// The count elements may carry a label (e.g. "2 projects") or a bare number, so each count is
15	// matched with a word-boundary regex on its number: this verifies the right value while tolerating
16	// surrounding label text, and — because the two seeded counts differ — proves each testid shows its
17	// own figure rather than the other.
18	import { test, expect, type Page } from '@playwright/test';
19	import { resetAndSeed } from '../support/seed';
20	
21	const contactRows = (page: Page) => page.locator('[data-testid^="contact-row-"]');
22	
23	test.describe('Client project and contact counts', () => {
24	  test("a client's detail page shows how many projects and contacts it has", async ({ page }) => {
25	    await resetAndSeed({
26	      clients: [
27	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
28	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
29	      ],
30	      projects: [
31	        { id: 1, name: 'Website Redesign', clientId: 1 },
32	        { id: 2, name: 'Billing System', clientId: 1 },
33	        // A project for a DIFFERENT client must not be counted here.
34	        { id: 3, name: 'Mobile App', clientId: 2 },
35	      ],
36	      contacts: [
37	        { id: 1, name: 'Alice Stone', email: 'alice@acme.test', role: 'Owner', clientId: 1 },
38	        { id: 2, name: 'Bob Reed', email: 'bob@acme.test', role: 'Billing', clientId: 1 },
39	        { id: 3, name: 'Eve Park', email: 'eve@acme.test', role: 'Legal', clientId: 1 },
40	        // A contact for a DIFFERENT client must not be counted here.
41	        { id: 4, name: 'Carol Vane', email: 'carol@globex.test', role: 'Manager', clientId: 2 },
42	      ],
43	    });
44	
45	    await page.goto('/clients/1');
46	
47	    await expect(page.getByTestId('client-detail-page')).toBeVisible();
48	    await expect(page.getByTestId('client-counts')).toBeVisible();
49	
50	    // Acme has exactly 2 projects and 3 contacts — the other client's are not counted.
51	    await expect(page.getByTestId('client-projects-count')).toHaveText(/\b2\b/);
52	    await expect(page.getByTestId('client-contacts-count')).toHaveText(/\b3\b/);
53	  });
54	
55	  test("a different client's page shows that client's own counts", async ({ page }) => {
56	    await resetAndSeed({
57	      clients: [
58	        { id: 1, name: 'Acme Corp', email: 'hello@acme.test' },
59	        { id: 2, name: 'Globex', email: 'contact@globex.test' },
60	      ],
61	      projects: [
62	        { id: 1, name: 'Website Redesign', clientId: 1 },
63	        { id: 2, name: 'Billing System', clientId: 1 },
64	        { id: 3, name: 'Mobile App', clientId: 2 },
65	      ],
66	      contacts: [
